powerpagecomponent.content:
{
  "source": "<!-- Common Loader -->
<div id="customLoader" class="cmdspp-loader-overlay" style="display:none;">
    <div class="cmdspp-loader-container">
        <div class="cmdspp-loader-spinner"></div>
        <div class="cmdspp-loader-text">
            Processing...
        </div>
    </div>
</div>

<style>
    .cmdspp-loader-overlay {
        position: absolute;
        inset: 0;
        display: flex;
        justify-content: center;
        align-items: center;
        z-index: 9999;
        /* background: rgba(255, 255, 255, 0.6); */
    }

    .cmdspp-loader-container {
        display: flex;
        flex-direction: column;
        align-items: center;
    }

    .cmdspp-loader-spinner {
        width: 50px;
        height: 50px;
        border: 6px solid #E6F3F3;
        border-top: 6px solid #1AA3A3;
        border-right: 6px solid #0B3A6F;
        border-radius: 50%;
        animation: cmdspp-spin 0.8s linear infinite;
    }

    .cmdspp-loader-text {
        margin-top: 12px;
        font-size: 14px;
        color: #000;
        font-family: Arial, sans-serif;
        text-align: center;
    }

    @keyframes cmdspp-spin {
        0% {
            transform: rotate(0deg);
        }
        100% {
            transform: rotate(360deg);
        }
    }
</style>

<script>
    function showLoader(message = "Processing...") {
        const loader = document.getElementById("customLoader");
        const loaderText = loader.querySelector(".cmdspp-loader-text");

        loaderText.textContent = message;
        loader.style.display = "flex";
    }

    function hideLoader() {
        document.getElementById("customLoader").style.display = "none";
    }
</script>"
}
